entries[269715] = { ["name"] = "Honorable Combatant's Sorcerous Scepter", ["text"] = "3 sec cast\nReagents:\nStar Wood , Umbra Shard (12), Expulsom (3)\nOptional Reagents:\nOptional Reagent Slot (#31)\nCraft an Honorable Combatant's Sorcerous Scepter.\nProfession:\nBattle for Azeroth Enchanting (85)\nTrainer:\nEnchantress Quinni\nZone:\nZuldazar\nCost:\n5\n25\n\nHorde\nHonorable Combatant's Sorcerous Scepter\nBinds when equipped\nRanged Wand\n2 - 4 Fire Damage Speed 2.00\n(1.5 damage per second)\n+18 Intellect\n+5 Stamina\nDurability 90 / 90\n50\nAlliance\nHonorable Combatant's Sorcerous Scepter\nBinds when equipped\nRanged Wand\n2 - 4 Frost Damage Speed 2.00\n(1.5 damage per second)\n+18 Intellect\n+5 Stamina\nDurability 90 / 90\n50" }
